}

.formula-menu-button,
.variable-button,
.solver-close {
    border: 0;
    background: transparent;
    color: var(--text);

    font-size: 14px;
    font-weight: 400;

    cursor: pointer;
}


/* ==================================================
   V9 — PHYSIK SOLVER
================================================== */

.physics-solver-panel {
    position: fixed;
    inset: 0;
    z-index: 2600;

    width: 100vw;
    height: 100vh;
    height: 100dvh;

    display: flex;
    flex-direction: column;

    padding:
        calc(22px + env(safe-area-inset-top))
        24px
        calc(28px + env(safe-area-inset-bottom));

    background: var(--bg);

    overflow-y: auto;
}

.physics-solver-panel.hidden {
