    align-items: center;
    justify-content: space-between;

    min-height: 44px;
}

.solver-heading {
    font-family:
        "Avenir Next",
        "Helvetica Neue",
        -apple-system,
        BlinkMacSystemFont,
        sans-serif;

    font-size: 21px;
    font-weight: 300;
}

.solver-close {
    color: var(--muted);
    font-size: 13px;
}

.physics-variable-picker,
.physics-solver-steps,
.solver-error {
    width: min(720px, 100%);
    margin-left: auto;
    margin-right: auto;
}

.physics-variable-picker {
    margin-top: 42px;

    text-align: center;
}

.physics-variable-picker.hidden {
