================================================== */

.timeline-screen {
    overflow-y: auto;
    overflow-x: hidden;
}

.timeline-shell {
    width: min(760px, 100%);

    min-height: 100vh;
    min-height: 100dvh;

    margin: 0 auto;

    padding:
        calc(82px + env(safe-area-inset-top))
        20px
        calc(72px + env(safe-area-inset-bottom));
}

.timeline-axis-note {
    margin:
        4px
        0
        34px
        clamp(106px, 23vw, 152px);

    color: var(--muted);

    font-size: 11px;
    line-height: 1.4;
    letter-spacing: 0.015em;
}

