    position: relative;

    display: flex;
    flex-direction: column;

    width: 100%;
}

.timeline-list::before {
    content: "";

    position: absolute;

    top: 0;
    bottom: 0;

    left: clamp(94px, 21vw, 138px);

    width: 1px;

    background:
        color-mix(
            in srgb,
            var(--text) 18%,
            transparent
        );

    pointer-events: none;
}

.timeline-entry {
    --timeline-gap: 14px;

    position: relative;
    z-index: 1;

    width: 100%;

    display: grid;
    grid-template-columns:
        clamp(80px, 18vw, 122px)
        32px
        minmax(0, 1fr);
    align-items: center;

    gap: 0;

    margin: var(--timeline-gap) 0 0;
    padding: 0;

    border: 0;
    background: transparent;
    color: var(--text);

    text-align: left;

    cursor: pointer;
}

.timeline-entry:first-child {
    margin-top: 0;
}

.timeline-time {
    padding-right: 12px;

    color: var(--muted);

    font-size: 10.5px;
    line-height: 1.25;

    text-align: right;
    font-variant-numeric: tabular-nums;
}

.timeline-mark {
    justify-self: center;

    width: 23px;
    height: 23px;

    display: flex;
    align-items: center;
    justify-content: center;

    border:
        1px solid
        color-mix(
            in srgb,
            var(--text) 30%,
            transparent
        );
    border-radius: 50%;

    background: var(--bg);
    color: var(--muted);

    font-family:
        Georgia,
        "Times New Roman",
        serif;

    font-size: 13px;
    line-height: 1;
}

.timeline-entry-content {
    min-width: 0;

    display: flex;
    flex-direction: column;

    padding:
        10px
        0
        10px
        12px;
}

.timeline-entry-title {
    overflow: hidden;

    color: var(--text);

    font-size: clamp(16px, 4vw, 20px);
    font-weight: 350;
    line-height: 1.25;

    text-overflow: ellipsis;
    white-space: nowrap;
}

.timeline-entry-kind {
    margin-top: 3px;

    color: var(--muted);

    font-size: 10.5px;
    line-height: 1.2;
    letter-spacing: 0.025em;
}

.timeline-entry:hover .timeline-mark,
.timeline-entry:focus-visible .timeline-mark {
    border-color:
        color-mix(
            in srgb,
            var(--text) 68%,
            transparent
        );

    color: var(--text);
}

.timeline-entry:focus-visible {
    outline: none;
}

.timeline-entry:focus-visible .timeline-entry-title {
    text-decoration: underline;
    text-decoration-thickness: 1px;
    text-underline-offset: 4px;
}

@media (max-width: 480px) {
    .timeline-shell {
        padding-left: 14px;
        padding-right: 16px;
    }

    .timeline-axis-note {
        margin-left: 101px;
    }

    .timeline-list::before {
        left: 91px;
    }

    .timeline-entry {
        grid-template-columns:
            78px
            27px
            minmax(0, 1fr);
    }

    .timeline-time {
        padding-right: 8px;

        font-size: 9.5px;
    }

    .timeline-mark {
        width: 20px;
        height: 20px;

        font-size: 12px;
    }

    .timeline-entry-content {
        padding-left: 10px;
    }
}


