/* ==================================================
   V25 — SANFTE BILD- UND SCREENÜBERGÄNGE
================================================== */

/* Gewöhnliche Seiten: kurz und zurückhaltend. */
.screen.active.screen-soft-enter {
    animation:
        screenSoftEnter
        260ms
        cubic-bezier(.22, .61, .36, 1)
        both;
}

@keyframes screenSoftEnter {
    from {
        opacity: 0;
        transform: translateY(3px);
    }

    to {
        opacity: 1;
        transform: translateY(0);
    }
}


/*
   Die drei Bildwelten nutzen das Zielbild selbst als Overlay.
   Dadurch entsteht ein echter Crossfade statt eines schwarzen
   Zwischenbildes.
*/
.screen-transition-overlay {
    position: fixed;
    inset: 0;

    z-index: 30000;

    width: 100vw;
    height: 100vh;
    height: 100dvh;

    opacity: 0;

    background-color: var(--bg);
    background-repeat: no-repeat;

    transform: scale(1.012);

    pointer-events: none;

    will-change:
        opacity,
        transform;

    transition:
        opacity
        430ms
        cubic-bezier(.22, .61, .36, 1),
        transform
        520ms
        cubic-bezier(.22, .61, .36, 1);
}

.screen-transition-overlay.image-crossfade.visible {
    opacity: 1;
    transform: scale(1);
}

/* Nach dem Screenwechsel verschwindet das identische Overlay schnell. */
.screen-transition-overlay.image-crossfade:not(.visible) {
    transition:
        opacity
        150ms
        ease-out,
        transform
        150ms
        ease-out;
}

@media (prefers-reduced-motion: reduce) {
    .screen.active.screen-soft-enter {
        animation: none !important;
    }

    .screen-transition-overlay {
        transition: none !important;
        transform: none !important;
    }
}


