#textsHubScreen.room-turn-source,
#textsHubScreen.room-turn-target,
#chessRoomScreen.room-turn-source,
#chessRoomScreen.room-turn-target {
    display: block !important;

    position: fixed !important;
    inset: 0 !important;

    width: 100vw !important;
    height: 100dvh !important;

    overflow: hidden !important;

    backface-visibility: hidden;
    -webkit-backface-visibility: hidden;

    will-change:
        transform,
        opacity,
        filter;
}

.room-turn-source {
    z-index: 21000 !important;

    opacity: 1;

    transform:
        perspective(1200px)
        translateX(0)
        rotateY(0deg)
        scale(1);

    filter: brightness(1);

    transition:
        transform 600ms cubic-bezier(.22,.61,.36,1),
        opacity 600ms cubic-bezier(.22,.61,.36,1),
        filter 600ms cubic-bezier(.22,.61,.36,1);
}

.room-turn-target {
    z-index: 21001 !important;

    opacity: .08;

    transition:
        transform 600ms cubic-bezier(.22,.61,.36,1),
        opacity 600ms cubic-bezier(.22,.61,.36,1),
        filter 600ms cubic-bezier(.22,.61,.36,1);
}

.room-turn-right.room-turn-target {
    transform-origin: left center;

    transform:
        perspective(1200px)
        translateX(42%)
        rotateY(-32deg)
        scale(.985);

    filter: brightness(.56);
}

.room-turn-left.room-turn-target {
    transform-origin: right center;

    transform:
        perspective(1200px)
        translateX(-42%)
        rotateY(32deg)
        scale(.985);

    filter: brightness(.56);
}

.room-turn-right.room-turn-source.room-turn-go {
    transform-origin: right center;

    transform:
        perspective(1200px)
        translateX(-38%)
        rotateY(25deg)
        scale(.985);

    opacity: .12;

    filter: brightness(.54);
}

.room-turn-left.room-turn-source.room-turn-go {
    transform-origin: left center;

    transform:
        perspective(1200px)
        translateX(38%)
        rotateY(-25deg)
        scale(.985);

    opacity: .12;

    filter: brightness(.54);
}

.room-turn-target.room-turn-go {
    transform:
        perspective(1200px)
        translateX(0)
        rotateY(0deg)
        scale(1) !important;

    opacity: 1;

    filter: brightness(1);
}

@media (prefers-reduced-motion: reduce) {
    .room-turn-source,
