html[data-theme="dark"] #filmRoomScreen .film-room-background {
    background-image: url("./film-room-night.png");
}

#filmRoomScreen .film-room-hotspot {
    position: absolute;
    z-index: 8;
    margin: 0;
    padding: 0;
    border: 0 !important;
    border-radius: 0 !important;
    background: transparent !important;
    color: transparent !important;
    box-shadow: none !important;
    outline: none !important;
    -webkit-tap-highlight-color: transparent;
    touch-action: manipulation;
}

/* V46: Nur das lose untere Filmband auf dem Tisch/Boden öffnet Filme.
   Dadurch ist die linke Wand vollständig frei für die Zurück-Geste. */
#filmRoomScreen .film-room-camera-hotspot {
    left: 0;
    top: 73.5%;
    width: 58%;
    height: 15.5%;
    z-index: 6;
}

/* Genug freie Wand links oben, ohne die Kamera zu überdecken. */
#filmRoomScreen .film-room-back-hotspot {
    left: 0;
    top: 0;
    width: 26%;
    height: 36%;
}


/* ==================================================
   V39 — FILME SORTIERUNG
================================================== */

.youtube-title-button {
    justify-self: center;
    padding: 10px 9px;
    border: 0;
    background: transparent;
    color: var(--text);
    font: inherit;
    cursor: pointer;
}

.youtube-sort-menu {
    position: fixed;
    top: calc(59px + env(safe-area-inset-top));
    left: 50%;
    z-index: 70000;
    width: min(290px, calc(100vw - 36px));
    transform: translateX(-50%);
    padding: 7px;
    border: 1px solid color-mix(in srgb, var(--text) 9%, transparent);
    border-radius: 16px;
    background: color-mix(in srgb, var(--surface) 97%, var(--bg));
    box-shadow: 0 16px 44px rgba(0, 0, 0, .16);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
}

.youtube-sort-option {
    position: relative;
    width: 100%;
    min-height: 43px;
    padding: 8px 34px 8px 11px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--text);
    text-align: left;
    font-size: 13px;
    cursor: pointer;
}

.youtube-sort-option:active {
    background: color-mix(in srgb, var(--text) 5%, transparent);
}

.youtube-sort-option.active::after {
    content: "✓";
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--muted);
    font-size: 12px;
}



/* ==================================================
   V43 — SCHWARZES-LOCH-UHR
================================================== */

#sessionFront.session-front-layer,
#universeCanvas.universe-canvas {
    background: #020304 !important;
}

#universeCanvas.universe-canvas {
    cursor: pointer;
    touch-action: manipulation;
    -webkit-tap-highlight-color: transparent;
}



/* ==================================================
   V45 — REUTERS / NACHRICHTEN-PROTOTYP
================================================== */

/* Schmale Wand rechts neben der Terrassentür. */
#filmRoomScreen .film-room-news-hotspot {
    left: 88%;
    top: 5%;
    width: 12%;
    height: 64%;
    z-index: 10;
}

.news-screen {
    background: var(--bg);
    color: var(--text);
}

.news-topbar {
    border-bottom: 1px solid color-mix(in srgb, var(--text) 5%, transparent);
}

.news-room-title {
    color: var(--text);
}

.news-refresh-button {
    justify-self: end;
    width: 44px;
    height: 44px;
    margin: 0;
    padding: 0 7px 1px 0;
    border: 0;
    background: transparent;
    color: var(--muted);
    font-size: 22px;
    font-weight: 300;
    line-height: 1;
}

.news-shell {
    width: min(100%, 720px);
    margin: 0 auto;
    padding: 12px max(19px, env(safe-area-inset-right)) calc(64px + env(safe-area-inset-bottom)) max(19px, env(safe-area-inset-left));
}

.news-categories {
    display: flex;
    gap: 18px;
    width: 100%;
    overflow-x: auto;
    padding: 5px 0 11px;
    border-bottom: 1px solid color-mix(in srgb, var(--text) 8%, transparent);
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
}

.news-categories::-webkit-scrollbar {
    display: none;
}

.news-category {
    flex: 0 0 auto;
    margin: 0;
    padding: 6px 0;
    border: 0;
    background: transparent;
    color: color-mix(in srgb, var(--muted) 88%, transparent);
    font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", sans-serif;
    font-size: 12px;
    font-weight: 420;
    letter-spacing: .01em;
    white-space: nowrap;
}

.news-category.active {
    color: var(--text);
}

.news-status {
    min-height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 12px 0 2px;
    color: var(--muted);
    font-size: 11px;
    text-align: center;
}

.news-status.busy::after {
    content: "";
    width: 3px;
    height: 3px;
    margin-left: 8px;
    border-radius: 50%;
    background: currentColor;
    animation: wiki-pulse 1s ease-in-out infinite;
}

.news-list {
    width: 100%;
}

.news-item {
    display: block;
    width: 100%;
    padding: 19px 0 18px;
    border-bottom: 1px solid color-mix(in srgb, var(--text) 8%, transparent);
    color: inherit;
    text-decoration: none;
}

.news-item:first-child {
    padding-top: 13px;
}

.news-item:last-child {
    border-bottom: 0;
}

.news-item-meta {
    display: flex;
    align-items: center;
    gap: 7px;
    margin-bottom: 7px;
    color: color-mix(in srgb, var(--muted) 88%, transparent);
    font-size: 10px;
    line-height: 1.25;
    letter-spacing: .018em;
}

.news-item-source {
    color: color-mix(in srgb, var(--text) 73%, transparent);
    font-weight: 520;
}

.news-item-dot {
    opacity: .45;
}

.news-item-title {
    margin: 0;
    color: var(--text);
    font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
    font-size: clamp(19px, 5vw, 23px);
    font-weight: 430;
    line-height: 1.22;
    letter-spacing: -.012em;
}

.news-empty {
    min-height: 46dvh;
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--muted);
    font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
    font-size: 15px;
    text-align: center;
}

.news-prototype-note {
    margin-top: 38px;
    padding-top: 16px;
    border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent);
    color: color-mix(in srgb, var(--muted) 72%, transparent);
    font-size: 9px;
    line-height: 1.5;
    text-align: center;
}

@media (max-width: 430px) {
    .news-shell {
        padding-left: 18px;
        padding-right: 18px;
    }

    .news-categories {
        gap: 17px;
    }
}


/* ==================================================
   V46 — FILM-HOTSPOT + REUTERS ROBUSTHEIT
================================================== */
.news-status.busy::after {
    content: "";
    display: inline-block;
    width: 0.45em;
    height: 0.45em;
    margin-left: 0.55em;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.38;
    animation: news-status-pulse 1.1s ease-in-out infinite alternate;
}

@keyframes news-status-pulse {
    from { opacity: 0.18; transform: scale(0.82); }
    to { opacity: 0.65; transform: scale(1); }
}


/* ==================================================
   V48 — NACHRICHTEN: GUARDIAN + PROPUBLICA
================================================== */

.news-room-title {
    letter-spacing: -.012em;
}

.news-shell {
    width: min(100%, 760px);
}

.news-categories {
    justify-content: flex-start;
    gap: 26px;
}

.news-category {
    font-size: 12px;
    letter-spacing: .015em;
}

.news-item {
    appearance: none;
