    font-size: 10px;
    font-weight: 560;
    letter-spacing: .045em;
    text-transform: uppercase;
}

.news-article-title {
    margin: 0;
    color: var(--text);
    font-family: "Iowan Old Style", "Palatino Linotype", Georgia, serif;
