   V49 — NACHRICHTEN: GUARDIAN + BELLINGCAT
================================================== */

.news-source-note {
    margin-top: 42px;
    padding-top: 16px;
    border-top: 1px solid color-mix(in srgb, var(--text) 7%, transparent);
    color: color-mix(in srgb, var(--muted) 70%, transparent);
    font-size: 9px;
    line-height: 1.55;
    text-align: center;
}

.news-list-view {
    width: 100%;
}

.news-item {
    display: flex;
    align-items: flex-start;
    gap: 17px;
}

.news-item-copy {
    min-width: 0;
    flex: 1 1 auto;
}

.news-item-thumb-wrap {
    width: clamp(88px, 24vw, 136px);
    aspect-ratio: 4 / 3;
    flex: 0 0 auto;
    overflow: hidden;
    border-radius: 2px;
    background: color-mix(in srgb, var(--text) 4%, transparent);
}

.news-item-thumb {
    display: block;
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: saturate(.86) contrast(.98);
}

.news-article-image-wrap {
    margin: 29px 0 31px;
}

.news-article-image {
    display: block;
    width: 100%;
    max-height: min(52dvh, 520px);
